<?php
declare(strict_types=1);
require_once __DIR__.'/access.php'; require_role('admin');
$pdo=db(); $id=(int)($_GET['content_id']??0); $stmt=$pdo->prepare('SELECT c.*,cl.name client_name,u.name employee_name FROM content c JOIN clients cl ON cl.id=c.client_id JOIN users u ON u.id=c.employee_id WHERE c.id=?');$stmt->execute([$id]);$content=$stmt->fetch();if(!$content){http_response_code(404);exit('Content not found.');}
$history=$pdo->prepare('SELECT h.*,u.name FROM content_status_history h JOIN users u ON u.id=h.user_id WHERE h.content_id=? ORDER BY h.created_at DESC');$history->execute([$id]);
